import{_ as o,o as r,c as n,a0 as t}from"./chunks/framework.CLbANrvH.js";const h=JSON.parse('{"title":"neuron 是什么？","description":"","frontmatter":{"title":"neuron 是什么？"},"headers":[],"relativePath":"zh/guide/intro.md","filePath":"zh/guide/intro.md","lastUpdated":1791849617000}'),a={name:"zh/guide/intro.md"};function i(l,e,s,c,d,u){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="neuron-是什么" tabindex="-1">neuron 是什么？ <a class="header-anchor" href="#neuron-是什么" aria-label="Permalink to &quot;neuron 是什么？&quot;">​</a></h1><p><code>neuron</code> 是一个**纯库形态（library-only）**的 Rust crate，可在任何 Rust 宿主进程中内嵌一个 OpenAI 兼容（以及 Anthropic Messages v1）的推理服务器。它加载模型权重，在三种 ML 框架之一上运行推理，并通过稳定的 HTTP 接口对外提供服务——全部发生在宿主自己的进程内部。</p><h2 id="为什么是库-而不是独立二进制" tabindex="-1">为什么是库，而不是独立二进制？ <a class="header-anchor" href="#为什么是库-而不是独立二进制" aria-label="Permalink to &quot;为什么是库，而不是独立二进制？&quot;">​</a></h2><p>大多数推理服务器（vLLM、ollama、llama.cpp server）都是独立守护进程——它们绑定一个端口，客户端指向它即可。对共享 GPU 服务器而言这是正确的模式，但对嵌入桌面应用或移动端二进制来说并不合适：</p><ul><li><strong>Tauri 2 桌面外壳</strong>应将 neuron 作为其自身二进制的一部分发布，而不是派生一个 sidecar 进程。</li><li><strong>Flutter 移动端</strong>（通过 <code>cargo-ndk</code>）将 neuron 编译为共享库，由 Kotlin/Swift 垫片加载。</li><li><strong>服务端进程</strong>（如 HTTP 网关或 Agent 编排器）已有自己的主循环——再引入 sidecar 只会增加摩擦。</li></ul><p><code>neuron::run_embedded(NeuronEmbedConfig { port: 8085, ... })</code> 返回一个 <code>NeuronHandle</code>，它拥有 axum 服务器的生命周期。宿主调用 <code>handle.request_shutdown()</code> + <code>handle.join().await</code> 实现优雅排空。若在不执行关闭的情况下直接丢弃 handle，将泄漏绑定的端口——类型系统保证了正确的生命周期。</p><h2 id="它提供什么" tabindex="-1">它提供什么 <a class="header-anchor" href="#它提供什么" aria-label="Permalink to &quot;它提供什么&quot;">​</a></h2><ul><li><strong>6 个能力面</strong>： <ul><li><strong>LLM</strong> — Qwen 2/2.5/3/3.5、Llama 2/3、Phi-3、Mistral、ChatGLM（candle）；Gemma 3（litert_lm 子进程）；40+ 模型家族（mistralrs 引擎，带 PagedAttention + ISQ）</li><li><strong>TTS</strong> — VoxCpm，基于 burn 0.21（中英文、语音克隆、预转换的 <code>.mpk</code> 权重）</li><li><strong>ASR</strong> — Whisper（candle-transformers）；<code>--features asr-audio</code> 时通过 <code>symphonia</code> 支持 MP3 / FLAC / OGG-Vorbis</li><li><strong>Rerank</strong> — BGE / mxbai / jina（candle 交叉编码器）+ Cohere HTTP 代理</li><li><strong>Embedding</strong> — MiniLM BERT（通过 <code>BatchLongest</code> 填充实现批量前向，支持 base64 输出）</li><li><strong>Vision</strong> — YOLOv8 / RT-DETR / DETR（candle），RF-DETR / Florence-2（可插拔 ONNX：ort / tract / onnxruntime），支持 LoRA 适配器注册</li></ul></li><li><strong>10+ 个 OpenAI 兼容 HTTP 路由</strong> + <code>/v1/messages</code> 上的 Anthropic Messages v1</li><li><strong>多来源模型注册表</strong>（HuggingFace、hf-mirror 中国 CDN、ModelScope），支持按引擎与按模型的来源覆盖</li><li><strong>多框架引擎</strong> — candle（默认）、burn（TTS）、litert_lm（端上 LLM）。按需选择，通过 feature flags 排除其余部分。</li><li><strong>稳定且定义清晰的线上格式（wire format）</strong> — 任何能与 OpenAI / vLLM / ollama / llama.cpp server / Anthropic SDK 配合的客户端，无需修改即可配合 neuron 使用</li></ul><h2 id="它不做什么" tabindex="-1">它不做什么 <a class="header-anchor" href="#它不做什么" aria-label="Permalink to &quot;它不做什么&quot;">​</a></h2><ul><li><strong>无独立二进制</strong> — neuron 仅为 <code>crate-type = [&quot;staticlib&quot;, &quot;cdylib&quot;, &quot;rlib&quot;]</code>。没有 <code>neuron serve</code> CLI。（如果需要独立服务器，参见历史项目 <code>prefrontal</code> 的 standalone 模式，它不属于 neuron。）</li><li><strong>无 SaaS / 无遥测 / 无回传</strong> — neuron 绝不发起出站网络调用，除非是通过 <code>POST /v1/models/pull</code> 显式触发的模型下载</li><li><strong>无内置 Agent 循环</strong> — neuron 只提供推理。Agent / 编排器由你自行基于 OpenAI 兼容的线上格式搭建</li><li><strong>无向量数据库 / 无 RAG</strong> — neuron 提供 embedding 能力，检索增强查询由调用方负责。使用 embedding 端点 + 你自己的向量库。</li><li><strong>无模型训练</strong> — neuron 只消费预训练权重。训练（LoRA、微调）不在范围内。</li></ul><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p><code>neuron</code> 以 <strong>Apache License 2.0</strong> 发布。<code>src/tts/voxcpm_burn/</code> 下内嵌的 VoxCpm 实现与 <code>src/vision/yolov8_arch.rs</code> 中的 YOLOv8 架构均为自研（净室重新实现），并重新授权以保持一致。第三方署名（candle、burn、mistral.rs、litert_lm、axum、tokio 等）记录在 <a href="https://github.com/ibloc/neuron/blob/main/LICENSE" target="_blank" rel="noreferrer"><code>LICENSE</code></a> 中。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/neuron/zh/guide/quick-start">快速开始</a> — 用 20 行代码在 Rust 二进制中嵌入 neuron</li><li><a href="/neuron/zh/concepts/architecture">架构</a> — 数据流、crate 布局、trait 接口面</li><li><a href="/neuron/zh/concepts/capabilities">能力</a> — 6 个模型面的详细说明</li><li><a href="/neuron/zh/concepts/embedding">宿主嵌入</a> — 具体的 Tauri / Flutter / 服务端集成模式</li></ul>',14)])])}const m=o(a,[["render",i]]);export{h as __pageData,m as default};
